from research_w3_external_features import ExternalProfiles,ExternalTreeFeatures
W=45/128
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--split',choices=['primary','confirm','oof'],required=True);a=ap.parse_args();start_guard();df,raw,y,splits,ref,old,fold=load_split(a.split);ext,_=external('both',df.id);testpath=ROOT/'data/test.csv';assert sha(testpath)=='ff7932747f27c5274de904194ac38b4d088ea4f9bb005ae74f0d619fb893a9b6';test=pd.read_csv(testpath);assert list(test.drop(columns='id'))==list(raw) and 'satisfaction' not in test;profile=ExternalProfiles().fit(test[list(raw)],test.id);out=ROOT/'research_artifacts'/f'w3_external_tree_{a.split}';out.mkdir(exist_ok=False);allpred=np.full(len(y),np.nan);old_all=np.full(len(y),np.nan);comparisons=[];params=json.loads((ROOT/'research_w3_tree_features_plan.json').read_text())['params']
 for k,(fi,vi) in enumerate(splits):
  start_guard();run=out/f'fold{k}';run.mkdir();r=ref[vi] if a.split=='oof' else ref;on=old[vi] if a.split=='oof' else old;P=outer_predictions(a.split,vi,df,fold);deep=np.load(ROOT/'research_artifacts'/('cb_deep_oof/raw_oof.npz' if a.split=='oof' else f'cb_deep_{a.split}/fold0/validation.npz'));d=deep['pred'][vi] if a.split=='oof' else deep['pred'];reconstructed=(45*P[:,0]+9*P[:,1]+18*P[:,2]+24*d+32*on)/128;delta=float(np.max(np.abs(reconstructed-r)));assert delta<1e-12;rec={'status':'preprocessing','started_utc':now(),'plan_sha256':sha(ROOT/'research_w3_external_profile_plan.json'),'feature_code_sha256':sha(ROOT/'research_w3_external_features.py'),'runner_sha256':sha(__file__),'params':params,'train_rows':len(fi),'valid_rows':len(vi),'unlabeled_external_rows':len(test),'external_file_sha256':sha(testpath),'outer_validation_features_or_labels_in_external_fit':False,'baseline_component_reconstruction_max_abs_diff':delta,'replacement_weight':W};dump(run/'result.json',rec);start=time.monotonic()
  try:
   with threadpool_limits(6):
    tr=ExternalTreeFeatures(profile);X=tr.fit_transform(raw.iloc[fi].reset_index(drop=True),y[fi],ext.iloc[fi].reset_index(drop=True));V=tr.transform(raw.iloc[vi].reset_index(drop=True),ext.iloc[vi].reset_index(drop=True));joblib.dump(tr,run/'transformer.joblib');rec.update(status='training',feature_width=X.shape[1]);dump(run/'result.json',rec);m=lgb.LGBMClassifier(**params);m.fit(X,y[fi]);pred=m.predict_proba(V)[:,1];m.booster_.save_model(str(run/'model.txt'));loaded=lgb.Booster(model_file=str(run/'model.txt'));again=loaded.predict(V,num_threads=6);reload_diff=float(np.max(np.abs(pred-again)));assert reload_diff<1e-12
   candidate=r+W*(pred-P[:,0]);assert np.isfinite(candidate).all() and ((candidate>=0)&(candidate<=1)).all();c=compare(y[vi],r,candidate);comparisons.append(c);allpred[vi]=pred;old_all[vi]=P[:,0];np.savez_compressed(run/'validation.npz',idx=vi,id=df.id.iloc[vi].to_numpy(),target=y[vi],pred=pred,candidate=candidate,v6=r,old_lgb=P[:,0]);rec.update(status='complete',completed_utc=now(),elapsed_seconds=time.monotonic()-start,vs_v6=c,model_reload_max_abs_diff=reload_diff,model_sha256=sha(run/'model.txt'));dump(run/'result.json',rec);print(json.dumps(rec,indent=2),flush=True);del m,loaded,X,V;gc.collect()
   if a.split=='oof' and c['delta_auc']<=0:dump(out/'result.json',{'status':'complete','eligible_for_next':False,'reason':'nonpositive fold','fold_comparisons':comparisons});return
  except BaseException as e:rec.update(status='failed',error=repr(e),ended_utc=now());dump(run/'result.json',rec);dump(out/'result.json',rec);raise
 vi=np.arange(len(y)) if a.split=='oof' else splits[0][1];pred=allpred[vi];candidate=ref+W*(pred-old_all[vi]);c=compare(y[vi],ref,candidate);np.savez_compressed(out/'validation.npz',idx=vi,id=df.id.iloc[vi].to_numpy(),target=y[vi],pred=pred,candidate=candidate,v6=ref,old_lgb=old_all[vi],**({'fold':fold} if fold is not None else {}));result={'status':'complete','variant':'external_profile_replacement','split':a.split,'vs_v6':c,'fold_comparisons':comparisons,'eligible_for_next':gate(c,a.split) and all(x['delta_auc']>0 for x in comparisons),'completed_utc':now()};dump(out/'result.json',result);print(json.dumps(result,indent=2),flush=True)
